#[test]
fn local_property_assignments_do_not_escape_reactive_values() {
    let source = r#"
        import { $state } from 'fict';
        function App(holder) {
            const count = $state(0);
            const local = {};
            const alias = local;
            const run = () => count;
            const { ...objectRest } = holder;
            const [first, ...arrayRest] = holder.items;
            const { callbacks: omittedCallbacks, ...excludedObjectRest } = holder;
            const overriddenObjectSpread = { ...holder, callbacks: {} };
            const prefixedArraySpread = [{}, ...holder.items];
            const directObjectSpread = { ...holder };
            const directArraySpread = [...holder.items];
            const objectRestAlias = objectRest;
            const arrayRestAlias = arrayRest;
            let replacedExternal = holder.callbacks;
            replacedExternal = {};
            let replacedInBranches = holder.callbacks;
            if (holder.first) replacedInBranches = {};
            else replacedInBranches = {};
            let replacedConditionally = holder.callbacks;
            replacedConditionally = holder.first ? {} : {};
            let replacedBySwitch = holder.callbacks;
            switch (holder.kind) {
                case 0: replacedBySwitch = {}; break;
                default: replacedBySwitch = {};
            }
            let replacedInForInit = holder.callbacks;
            for (replacedInForInit = {}; false;) {}
            let replacedInWhileTest = holder.callbacks;
            while ((replacedInWhileTest = {}, false)) {}
            let replacedInFinally = holder.callbacks;
            try { if (holder.fail) throw 0; }
            finally { replacedInFinally = {}; }
            let replacedBeforeLabeledBreak = holder.callbacks;
            done: { replacedBeforeLabeledBreak = {}; break done; }
            const getLocal = () => ({});
            const getLocalConfig = () => ({ callbacks: {} });
            const getEitherLocal = () => holder.enabled ? {} : [];
            const getPrimitive = () => 1;
            const getUndefined = () => {};
            const getAsync = async () => holder.callbacks;
            function* getIterator() { yield holder.callbacks; }
            class LocalFactory {}
            class PrimitiveFactory { constructor() { return 1; } }
            const makeLocal = () => new LocalFactory();
            const makeDate = () => new Date();
            const makeArray = () => Array.from([]);
            const externalItems = [holder.item];
            const makeSlicedItems = () => externalItems.slice();
            const slicedItems = externalItems.slice();
            const concatenatedItems = externalItems.concat();
            const filteredItems = externalItems.filter(() => true);
            const reversedItems = externalItems.toReversed();
            const sortedItems = externalItems.toSorted(() => 0);
            const splicedItems = externalItems.toSpliced(0, 0);
            const replacedItems = externalItems.with(0, {});
            const mappedItems = externalItems.map(item => item);
            const flatMappedItems = externalItems.flatMap(item => [item]);
            const flattenedItems = [externalItems].flat();
            const fromItems = Array.from(externalItems);
            const ofItems = Array.of(holder.item);
            const removedItems = externalItems.splice(0, 1);
            const localItem = {};
            const localItems = [localItem];
            const localSlicedItems = localItems.slice();
            const localConcatenatedItems = localItems.concat();
            const localFilteredItems = localItems.filter(() => true);
            const localReversedItems = localItems.toReversed();
            const localSortedItems = localItems.toSorted(() => 0);
            const localSplicedItems = localItems.toSpliced(0, 0);
            const localReplacedItems = localItems.with(0, localItem);
            const localFromItems = Array.from(localItems);
            const localOfItems = Array.of(localItem);
            local.run = run;
            alias.next ??= () => count;
            objectRest.run = run;
            arrayRest.run = run;
            objectRestAlias.run = run;
            arrayRestAlias.run = run;
            excludedObjectRest.callbacks = {};
            excludedObjectRest.callbacks.run = run;
            overriddenObjectSpread.callbacks.run = run;
            prefixedArraySpread[0].run = run;
            directObjectSpread.callbacks = run;
            directArraySpread[0] = run;
            slicedItems[0] = run;
            concatenatedItems[0] = run;
            filteredItems[0] = run;
            reversedItems[0] = run;
            sortedItems[0] = run;
            splicedItems[0] = run;
            replacedItems[0] = run;
            removedItems[0] = run;
            mappedItems[0] = run;
            flatMappedItems[0] = run;
            flattenedItems[0] = run;
            fromItems[0] = run;
            ofItems[0] = run;
            externalItems.slice()[0] = run;
            externalItems.slice().run = run;
            makeSlicedItems()[0] = run;
            makeSlicedItems().run = run;
            const madeSlicedItems = makeSlicedItems();
            madeSlicedItems[0] = run;
            localSlicedItems[0].run = run;
            localConcatenatedItems[0].run = run;
            localFilteredItems[0].run = run;
            localReversedItems[0].run = run;
            localSortedItems[0].run = run;
            localSplicedItems[0].run = run;
            localReplacedItems[0].run = run;
            localFromItems[0].run = run;
            localOfItems[0].run = run;
            ({}).run = run;
            ([]).run = run;
            new Date().run = run;
            new Map().run = run;
            Array.from([]).run = run;
            Array.of(1).run = run;
            Array().run = run;
            Object({}).run = run;
            Number().run = run;
            Date().run = run;
            Function().run = run;
            new Object({}).run = run;
            new Object(new Date()).run = run;
            (() => ({}))().run = run;
            (() => 1)().run = run;
            (() => {})().run = run;
            const storedDate = new Date();
            storedDate.run = run;
            const storedArray = Array.from([]);
            storedArray.run = run;
            const storedObjectWrapper = Object({});
            storedObjectWrapper.run = run;
            const nullPrototype = Object.create(null);
            nullPrototype.run = run;
            Object.create(null).run = run;
            const { callbacks: localCallbacks } = getLocalConfig();
            localCallbacks.run = run;
            const { ...opaqueObjectRest } = holder.getConfig();
            opaqueObjectRest.run = run;
            const [, ...opaqueArrayRest] = holder.getCallbacks();
            opaqueArrayRest[0] = run;
            let assignedLocalCallbacks;
            ({ callbacks: assignedLocalCallbacks } = getLocalConfig());
            assignedLocalCallbacks.run = run;
            replacedExternal.run = run;
            replacedInBranches.run = run;
            replacedConditionally.run = run;
            replacedBySwitch.run = run;
            replacedInForInit.run = run;
            replacedInWhileTest.run = run;
            replacedInFinally.run = run;
            replacedBeforeLabeledBreak.run = run;
            getLocal().run = run;
            getEitherLocal().run = run;
            const eitherLocal = getEitherLocal();
            eitherLocal.run = run;
            getPrimitive().run = run;
            const primitive = getPrimitive();
            primitive.run = run;
            getUndefined().run = run;
            getAsync().run = run;
            getIterator().run = run;
            const undefinedValue = getUndefined();
            undefinedValue.run = run;
            const asyncValue = getAsync();
            asyncValue.run = run;
            const iterator = getIterator();
            iterator.run = run;
            makeLocal().run = run;
            makeDate().run = run;
            makeArray().run = run;
            const madeLocal = makeLocal();
            madeLocal.run = run;
            const madeDate = makeDate();
            madeDate.run = run;
            const madeArray = makeArray();
            madeArray.run = run;
            new LocalFactory().run = run;
            new PrimitiveFactory().run = run;
            holder.label += run;
            [holder.label, local.next] = ["safe", run];
            ({ label: holder.label, next: local.next } = { label: "safe", next: run });
            if (holder.detach) holder = {};
            else holder = {};
            holder.run = run;
            local.run();
            alias.next?.();
            return count;
        }
    "#;
    let output = build_hir(
        source,
        options(OxcSourceLanguage::JavaScript),
        &HirBuildOptions::default(),
    );
    assert!(output.hir.is_some(), "{:?}", output.diagnostics);
    assert!(
        output.diagnostics.iter().all(|diagnostic| {
            !matches!(
                diagnostic.code.as_str(),
                "FICT-S002" | "FICT-R002" | "FICT-R005"
            )
        }),
        "local slots and non-retaining assignments must remain valid: {:?}",
        output.diagnostics
    );
}

#[test]
fn fresh_array_results_preserve_precise_local_element_provenance() {
    let source = r#"
        import { $state } from 'fict';
        function App(holder) {
            const count = $state(0);
            const run = () => count;
            const local = {};
            const mixed = [local, holder.item];
            const sliced = mixed.slice(0, 1);
            const slicedAgain = sliced.slice();
            const concatenated = mixed.concat();
            const reversed = mixed.toReversed();
            const spliced = mixed.toSpliced(1, 1);
            const unchanged = mixed.toSpliced();
            const replaced = mixed.with(1, local);
            const from = Array.from(mixed);
            const of = Array.of(local, holder.item);
            const objectValue = [].concat({ child: local });
            const detachedNested = Array.of({ child: holder.item });
            const calledArray = Array(local);
            const constructedArray = new Array(local);
            const holes = new Array(2);
            const removed = mixed.splice();
            sliced[0].run = run;
            slicedAgain[0].run = run;
            concatenated[0].run = run;
            reversed[1].run = run;
            spliced[0].run = run;
            unchanged[0].run = run;
            replaced[1].run = run;
            from[0].run = run;
            of[0].run = run;
            objectValue[0].child.run = run;
            detachedNested[0].child = {};
            detachedNested[0].child.run = run;
            calledArray[0].run = run;
            constructedArray[0].run = run;
            holes[0] = run;
            removed[0].run = run;
            return count;
        }
    "#;
    let output = build_hir(
        source,
        options(OxcSourceLanguage::JavaScript),
        &HirBuildOptions::default(),
    );
    assert!(output.hir.is_some(), "{:?}", output.diagnostics);
    assert!(
        output.diagnostics.iter().all(|diagnostic| {
            !matches!(
                diagnostic.code.as_str(),
                "FICT-S002" | "FICT-R002" | "FICT-R005"
            )
        }),
        "fresh array results must retain only the selected external element identities: {:?}",
        output.diagnostics
    );
}

#[test]
fn large_array_results_bound_provenance_expansion() {
    let source = r#"
        import { $state } from 'fict';
        function App() {
            const count = $state(0);
            const run = () => count;
            const huge = new Array(4294967295);
            const reversed = huge.toReversed();
            const filtered = huge.filter(() => true);
            huge.reverse();
            reversed[0] = run;
            filtered[0] = run;
            huge[0] = run;
            return count;
        }
    "#;
    let output = build_hir(
        source,
        options(OxcSourceLanguage::JavaScript),
        &HirBuildOptions::default(),
    );
    assert!(output.hir.is_some(), "{:?}", output.diagnostics);
    assert!(
        output.diagnostics.iter().all(|diagnostic| {
            !matches!(
                diagnostic.code.as_str(),
                "FICT-S002" | "FICT-R002" | "FICT-R005"
            )
        }),
        "large fresh arrays must remain local without enumerating every slot: {:?}",
        output.diagnostics
    );
}

#[test]
fn in_place_array_mutations_preserve_local_storage() {
    let source = r#"
        import { $state } from 'fict';
        function App(holder) {
            const count = $state(0);
            const run = () => count;
            const local = {};
            const reversed = [holder.item, local];
            const reversedAlias = reversed;
            const sorted = [local];
            const sortedWithComparator = [local, {}];
            const shifted = [{}, local];
            const unshifted = [local];
            const pushed = [{}];
            const inserted = [{}];
            const spliced = [{}, local];
            const copiedWithin = [local, holder.item];
            const filled = [holder.item];
            const popped = [{}, holder.item];
            const snapshottedSource = [local, holder.item];
            const snapshotted = snapshottedSource.slice();
            reversedAlias.reverse();
            sorted.sort();
            sortedWithComparator.sort(() => 0);
            shifted.shift();
            unshifted.unshift({});
            pushed.push(local);
            inserted.splice(1, 0, local);
            spliced.splice(0, 1);
            copiedWithin.copyWithin(1, 0, 1);
            filled.fill(local);
            popped.pop();
            popped.push(local);
            snapshottedSource.reverse();
            reversed[0].run = run;
            sorted[0].run = run;
            sortedWithComparator[0].run = run;
            shifted[0].run = run;
            unshifted[1].run = run;
            pushed[1].run = run;
            inserted[1].run = run;
            spliced[0].run = run;
            copiedWithin[1].run = run;
            filled[0].run = run;
            popped[1].run = run;
            snapshotted[0].run = run;
            return count;
        }
    "#;
    let output = build_hir(
        source,
        options(OxcSourceLanguage::JavaScript),
        &HirBuildOptions::default(),
    );
    assert!(output.hir.is_some(), "{:?}", output.diagnostics);
    assert!(
        output.diagnostics.iter().all(|diagnostic| {
            !matches!(
                diagnostic.code.as_str(),
                "FICT-S002" | "FICT-R002" | "FICT-R005"
            )
        }),
        "in-place mutations must retain local element identities: {:?}",
        output.diagnostics
    );
}

#[test]
fn platform_resource_instances_are_local_callback_storage() {
    let source = r#"
        import { $state } from 'fict';
        function App() {
            const count = $state(0);
            const run = () => count;
            const WorkerAlias = Worker;
            const worker = new WorkerAlias('./worker.js');
            const sharedWorker = new SharedWorker('./shared-worker.js');
            const channel = new BroadcastChannel('events');
            const eventSource = new EventSource('/events');
            const messageChannel = new MessageChannel();
            const socket = new WebSocket('ws://localhost');
            const request = new XMLHttpRequest();
            const controller = new AbortController();
            worker.onmessage = run;
            sharedWorker.port.onmessage = run;
            channel.onmessage = run;
            eventSource.onmessage = run;
            messageChannel.port1.onmessage = run;
            socket.onmessage = run;
            request.onreadystatechange = run;
            controller.signal.onabort = run;
            return count;
        }
    "#;
    let output = build_hir(
        source,
        options(OxcSourceLanguage::JavaScript),
        &HirBuildOptions::default(),
    );
    assert!(output.hir.is_some(), "{:?}", output.diagnostics);
    assert!(
        output.diagnostics.iter().all(|diagnostic| {
            !matches!(
                diagnostic.code.as_str(),
                "FICT-S002" | "FICT-R002" | "FICT-R005"
            )
        }),
        "fresh platform resources retain callbacks only on their local instances: {:?}",
        output.diagnostics
    );
}

#[test]
