#[test]
fn immediately_invoked_functions_propagate_parameter_invalidations() {
    for (name, setup, call) in [
        (
            "arrow IIFE",
            "",
            "(target => { target.forEach = null; })(values);",
        ),
        (
            "function IIFE",
            "",
            "(function (target) { target.forEach = null; })(values);",
        ),
        (
            "sequence IIFE",
            "",
            "(0, target => { target.forEach = null; })(values);",
        ),
        (
            "destructured IIFE",
            "const box = { target: values };",
            "(({ target }) => { target.forEach = null; })(box);",
        ),
        (
            "rest IIFE",
            "",
            "((...targets) => { targets[0].forEach = null; })(values);",
        ),
        (
            "immediate conditional callable",
            "function inspect(target) { return target.length; } function mutate(target) { target.forEach = null; }",
            "(choose ? inspect : mutate)(values);",
        ),
        (
            "immediate logical callable",
            "function inspect(target) { return target.length; } function mutate(target) { target.forEach = null; }",
            "(mutate || inspect)(values);",
        ),
        (
            "sequenced conditional callable",
            "function inspect(target) { return target.length; } function mutate(target) { target.forEach = null; }",
            "(0, choose ? inspect : mutate)(values);",
        ),
        (
            "assigned conditional callable",
            "function inspect(target) { return target.length; } function mutate(target) { target.forEach = null; } let run;",
            "(run = choose ? inspect : mutate)(values);",
        ),
        (
            "conditional inline callable",
            "",
            "(choose ? target => target.length : target => { target.forEach = null; })(values);",
        ),
        (
            "conditional external callable",
            "function inspect(target) { return target.length; }",
            "(choose ? inspect : External)(values);",
        ),
    ] {
        let source = format!(
            r#"
                import {{ $state }} from 'fict';
                function App(External, choose) {{
                    const count = $state(0);
                    const values = [];
                    {setup}
                    {call}
                    values.forEach(() => count);
                    return count;
                }}
            "#
        );
        let output = build_hir(
            &source,
            options(OxcSourceLanguage::JavaScript),
            &HirBuildOptions::default(),
        );
        assert!(output.hir.is_none(), "{name}: expected a hard diagnostic");
        assert!(
            output.diagnostics.iter().any(|diagnostic| {
                diagnostic.code.as_str() == "FICT-R005"
                    && diagnostic.primary_span.is_some_and(|span| {
                        &source[span.start() as usize..span.end() as usize] == "() => count"
                    })
            }),
            "{name}: expected FICT-R005 on callback, got {:?}",
            output.diagnostics
        );
    }
}

#[test]
fn iife_initializers_resolve_nested_invocation_results() {
    let source = r#"
        import { $state } from 'fict';
        function identity(value) { return value; }
        function App() {
            const count = $state(0);
            const value = (() => identity(1))();
            return count() + value;
        }
    "#;
    let output = build_hir(
        source,
        options(OxcSourceLanguage::JavaScript),
        &HirBuildOptions::default(),
    );
    assert!(
        output.hir.is_some(),
        "unexpected diagnostics: {:?}",
        output.diagnostics
    );
}

#[test]
fn iife_initializers_preserve_nested_callable_result_effects() {
    for (name, observation, expected_hir) in [
        ("uninvoked nested result", "void run;", true),
        ("invoked nested result", "run();", false),
    ] {
        let source = format!(
            r#"
                import {{ $state }} from 'fict';
                function App() {{
                    const count = $state(0);
                    const values = [];
                    function create() {{
                        return () => {{ values.forEach = null; }};
                    }}
                    const run = (() => create())();
                    {observation}
                    values.forEach(() => count);
                    return count;
                }}
            "#
        );
        let output = build_hir(
            &source,
            options(OxcSourceLanguage::JavaScript),
            &HirBuildOptions::default(),
        );
        assert_eq!(
            output.hir.is_some(),
            expected_hir,
            "{name}: unexpected nested callable result outcome: {:?}",
            output.diagnostics
        );
    }
}

